def make_raw_header(style: str) -> pd.DataFrame:
    """지정한 연도 레이아웃의 헤더 영역 DataFrame(header=None 형태)을 만든다.

    Args:
        style: "2016" | "2017" | "2018" | "2025"

    Returns:
        11행 x N열 DataFrame. 데이터 행은 포함하지 않는다
        (find_columns 는 상위 11행만 스캔한다: 전처리.py:138).
    """
    if style not in SHAPES:
        raise KeyError(f"알 수 없는 레이아웃: {style} (가능: {sorted(SHAPES)})")
    n_rows, n_cols = SHAPES[style]
    df = pd.DataFrame(index=range(n_rows), columns=range(n_cols), dtype=object)
    for (r, c), value in CELLS[style].items():
        df.iat[r, c] = value
    return df


def make_raw_with_rows(style: str, data_rows: list) -> pd.DataFrame:
    """헤더 + 임의의 데이터 행을 붙인 DataFrame 을 만든다.

    data_rows 각 항목은 {열 인덱스: 값} dict 또는 전체 길이 리스트.
    """
    head = make_raw_header(style)
    n_cols = head.shape[1]
    rows = []
    for row in data_rows:
        filled = [None] * n_cols
        if isinstance(row, dict):
            for col, value in row.items():
                filled[col] = value
        else:
            for i, value in enumerate(row[:n_cols]):
                filled[i] = value
        rows.append(filled)
    tail = pd.DataFrame(rows, columns=range(n_cols), dtype=object)
    return pd.concat([head, tail], ignore_index=True)
